export const COURSES_PER_PAGE = 12;

export function getCsvCourse(id: string): CsvCourse | undefined {
  return CSV_COURSES.find((c) => c.id === id);
}

export function getCsvCoursePage(page: number): CsvCourse[] {
  const start = (page - 1) * COURSES_PER_PAGE;
  return CSV_COURSES.slice(start, start + COURSES_PER_PAGE);
}

export const TOTAL_CSV_PAGES = Math.ceil(CSV_COURSES.length / COURSES_PER_PAGE);

